import { parseCommandLine } from "./cli/parser.mjs";
import { buildStruct, FormatFieldError } from "./construct/int8ul_struct.mjs";
import { formatPythonBytesLiteral } from "./format/python_bytes_repr.mjs";

function writeToStream(streamName, text) {
  if (streamName === "stderr") {
    process.stderr.write(text);
    return;
  }

  process.stdout.write(text);
}

export function run(argv = process.argv) {
  const parseResult = parseCommandLine(argv);

  if (parseResult.status === "help" || parseResult.status === "error") {
    writeToStream(parseResult.stream, parseResult.text);
    return parseResult.exitCode;
  }

  const data = buildStruct({
    field1: parseResult.values.a,
    field2: parseResult.values.b,
  });

  writeToStream("stdout", `${formatPythonBytesLiteral(data)}\n`);
  return 0;
}

export function runAndExit(argv = process.argv) {
  try {
    process.exitCode = run(argv);
  } catch (error) {
    if (error instanceof FormatFieldError) {
      writeToStream("stderr", `construct.core.FormatFieldError: ${error.message}\n`);
      process.exitCode = 1;
      return;
    }

    throw error;
  }
}

