    );
    this.fieldName = fieldName;
    this.name = "FormatFieldError";
    this.value = value;
  }
}

function assertInt8ul(fieldName, value) {
  if (value < 0n || value > 255n) {
    throw new FormatFieldError(fieldName, value);
  }

  return Number(value);
}

export function buildStruct(fields) {
